import numpy as np

def naive_init(input_size, output_size, seed):
    return np.random.RandomState(seed).normal(scale=1.0, size=(input_size, output_size))

def xavier_init(input_size, output_size, seed):
    limit = np.sqrt(6 / (input_size + output_size))
    return np.random.RandomState(seed).uniform(-limit, limit, size=(input_size, output_size))

def tanh(x):
    return np.tanh(x)

layer_sizes = [100, 100, 100, 100, 100]  # 4 stacked layers, each 100 wide
x = np.random.RandomState(0).normal(size=(1, layer_sizes[0]))

print("Naive initialization, activation std deviation per layer:")
naive_x = x.copy()
for i in range(len(layer_sizes) - 1):
    weights = naive_init(layer_sizes[i], layer_sizes[i + 1], seed=i)
    naive_x = tanh(naive_x @ weights)
    print(f"  Layer {i + 1}: std = {naive_x.std():.6f}")

print("\nXavier initialization, activation std deviation per layer:")
xavier_x = x.copy()
for i in range(len(layer_sizes) - 1):
    weights = xavier_init(layer_sizes[i], layer_sizes[i + 1], seed=i)
    xavier_x = tanh(xavier_x @ weights)
    print(f"  Layer {i + 1}: std = {xavier_x.std():.6f}")
